package com.fulllock.probe;
import android.graphics.*;import android.graphics.drawable.Drawable;import android.os.SystemClock;import java.util.function.BooleanSupplier;
/** Paint only: no View, touch listener, gesture or click target. */
final class AcceptFrameDrawable extends Drawable {
 private final RectF rect,inside;private final Path exclusion=new Path();private final Matrix gradientMatrix=new Matrix();private final SweepGradient gradient;private int cycle=2400;private final float d;private final int color;private final boolean rgb,pulse;private final BooleanSupplier current;private final Paint paint=new Paint(3);private final Runnable frame=this::invalidateSelf;
 AcceptFrameDrawable(RectF rect,float d,int color,boolean rgb,boolean pulse,BooleanSupplier current){this.inside=new RectF(rect);this.rect=new RectF(rect);this.rect.inset(-3*d,-3*d);this.d=d;this.color=color;this.rgb=rgb;this.pulse=pulse;this.current=current;exclusion.addRoundRect(this.inside,9*d,9*d,Path.Direction.CW);gradient=rgb?new SweepGradient(this.rect.centerX(),this.rect.centerY(),new int[]{0xFF22C55E,0xFF06B6D4,0xFF6366F1,0xFFEC4899,0xFF22C55E},null):null;}
 AcceptFrameDrawable(RectF rect,float d,int color,boolean rgb,boolean pulse,int cycle,BooleanSupplier current){this(rect,d,color,rgb,pulse,current);this.cycle=Math.max(500,Math.min(5000,cycle));}
 public void draw(Canvas canvas){if(!current.getAsBoolean())return;boolean animate=android.animation.ValueAnimator.areAnimatorsEnabled();float wave=(float)(.5+.5*Math.sin(SystemClock.uptimeMillis()*Math.PI*2/cycle));int save=canvas.save();canvas.clipOutPath(exclusion);paint.setStyle(Paint.Style.STROKE);paint.setColor(color);if(rgb){gradientMatrix.setRotate(animate?(SystemClock.uptimeMillis()%8000)*360f/8000:0,rect.centerX(),rect.centerY());gradient.setLocalMatrix(gradientMatrix);paint.setShader(gradient);}else paint.setShader(null);paint.setStrokeWidth(10*d);paint.setAlpha(animate&&pulse?(int)(22+22*wave):32);canvas.drawRoundRect(rect,12*d,12*d,paint);paint.setStrokeWidth(5*d);paint.setAlpha(animate&&pulse?(int)(180+75*wave):255);canvas.drawRoundRect(rect,12*d,12*d,paint);canvas.restoreToCount(save);if(animate&&(rgb||pulse))scheduleSelf(frame,SystemClock.uptimeMillis()+33);}
 public void setAlpha(int alpha){}public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}
}
